async function basecampBoardUrl(ctx) {
  const org = need(ctx.opts, "org", "Basecamp");
  const projectId = need(ctx.opts, "bcProject", "Basecamp");
  const projects = arr(await ctx.call("GET", `basecamp/buckets/${enc(org)}`));
  const project = projects.find((p) => String(p.id) === projectId);
  const board = arr(project?.dock).find((d) => d.name === "kanban_board" && d.enabled !== false);
  if (!board?.url)
    throw new CliError("not_found", `Basecamp project ${projectId} has no card table.`, {
      hint: "Run `betterbugs list basecamp-projects --org <id>`."
    });
  return String(board.url);
}
