var NOTIFICATION_TYPES = {
  welcome: "WELCOME",
  sessions: "SESSION_NOTIFICATIONS",
  "guest-roles": "GUEST_ROLE_NOTIFICATIONS",
  automations: "AUTOMATION_NOTIFICATIONS",
  apologies: "APOLOGY_EMAILS",
  critical: "CRITICAL"
};
var NOTIFICATION_NAMES = Object.fromEntries(Object.entries(NOTIFICATION_TYPES).map(([k, v]) => [v, k]));
function notificationRows(optedOut) {
  const all = optedOut.includes("ALL");
  return Object.entries(NOTIFICATION_TYPES).map(([type, api]) => ({
    type,
    emails: all || optedOut.includes(api) ? "off" : "on"
  }));
}
function notificationTypes(values, flag) {
  return splitList(values).map((v) => {
    const key = v.toLowerCase();
    if (key === "all") return "ALL";
    const api = NOTIFICATION_TYPES[key];
    if (!api)
      throw usageError(
        `Unknown email type "${v}" in ${flag}.`,
        `Use: ${[...Object.keys(NOTIFICATION_TYPES), "all"].join(", ")}.`
      );
    return api;
  });
}
var notificationOutput = (optedOut) => {
  const rows = notificationRows(optedOut);
  return {
    data: { emails: rows, allOff: optedOut.includes("ALL") },
    human: () => table(
      ["EMAILS", "STATE"],
      rows.map((r) => [r.type, r.emails])
    )
  };
};
