var updateNotifications = defineCommand({
  path: ["update", "notifications"],
  summary: "Turn BetterBugs emails on or off",
  flags: [
    {
      flags: "--off <types...>",
      description: "Stop these emails (or all)",
      type: "list",
      completions: [...Object.keys(NOTIFICATION_TYPES), "all"]
    },
    {
      flags: "--on <types...>",
      description: "Receive these emails again (all clears every opt-out)",
      type: "list",
      completions: [...Object.keys(NOTIFICATION_TYPES), "all"]
    }
  ],
  examples: [
    "betterbugs update notifications --off welcome,apologies",
    "betterbugs update notifications --on all"
  ],
  output: "{ emails[{ type, emails }], allOff }",
  phase: 6,
  async run(rt, _args, opts) {
    const off = notificationTypes(opts.off, "--off");
    const on = notificationTypes(opts.on, "--on");
    if (!off.length && !on.length) throw usageError("Nothing to change.", "Pass --off and/or --on.");
    const both = off.filter((t) => on.includes(t));
    if (both.length) throw usageError(`${NOTIFICATION_NAMES[both[0]] ?? "all"} is in both --on and --off.`);
    const api = await rt.api();
    const current2 = new Set((await api.getNotificationPreferences()).optedOutTypes ?? []);
    if (on.includes("ALL")) current2.clear();
    for (const t of on) current2.delete(t);
    if (on.length && current2.has("ALL")) {
      current2.delete("ALL");
      for (const t of Object.values(NOTIFICATION_TYPES)) if (!on.includes(t)) current2.add(t);
    }
    for (const t of off) current2.add(t);
    const prefs = await api.setNotificationOptOuts([...current2]);
    return notificationOutput(prefs.optedOutTypes ?? [...current2]);
  }
});
