async function trashedProject(api, ws, ref) {
  const needle = ref.trim();
  const trashed = [];
  for (let skip = 0; skip < 2e3; skip += 50) {
    const page = await api.listProjects(ws, { skip, take: 50 }, { archived: true });
    for (const p of page.list) if (p.isArchived) trashed.push({ id: p.id, name: p.name });
    if (page.list.length < 50 || page.total !== void 0 && skip + 50 >= page.total) break;
  }
  if (OBJECT_ID2.test(needle)) return { id: needle, name: trashed.find((p) => p.id === needle)?.name };
  const match = trashed.filter((p) => p.name.toLowerCase() === needle.toLowerCase());
  if (match.length === 1) return match[0];
  throw usageError(
    match.length ? `More than one project in the trash is named "${needle}".` : `No project named "${needle}" is in the trash.`,
    trashed.length ? `Use a project id. In the trash:
${trashed.map((p) => `  ${p.id}  ${p.name}`).join("\n")}` : "The trash has no projects."
  );
}
