function respondAccess(approve) {
  return defineCommand({
    path: [approve ? "approve" : "reject", "access-request"],
    summary: approve ? "Let someone into a private project" : "Turn down a request to join a private project",
    args: [{ name: "request", description: "Request id, or the requester\u2019s email", required: true }],
    flags: approve ? [ROLE_FLAG] : [],
    scopes: ["project.getById", "project.addMember"],
    output: "{ id, email, status: approved|rejected, role }",
    phase: 6,
    async run(rt, [ref], opts) {
      const { ws, project, api } = await target(rt);
      const needle = ref.trim().toLowerCase();
      const request = (await api.listAccessRequests(ws.id, project.id)).find(
        (r) => r.id === ref.trim() || r.user?.email?.toLowerCase() === needle
      );
      if (!request?.requestToken)
        throw new CliError(
          "not_found",
          `No pending access request "${ref}" in ${project.name ?? project.id}.`,
          {
            hint: "Run `betterbugs list access-requests`."
          }
        );
      const res2 = await api.respondAccessRequest(ws.id, project.id, {
        requestToken: request.requestToken,
        action: approve ? "approved" : "rejected",
        ...approve && opts.role ? { role: roleToApi(opts.role) } : {}
      });
      const data = {
        id: request.id,
        email: request.user?.email ?? null,
        status: approve ? "approved" : "rejected",
        role: approve ? lower(res2.role) ?? "member" : null
      };
      return { data, human: `${approve ? "Approved" : "Rejected"} ${data.email ?? data.id}.` };
    }
  });
}
